package com.whitelabel.cdn.filter;

import org.springframework.cloud.gateway.filter.GatewayFilterChain;
import org.springframework.cloud.gateway.filter.GlobalFilter;
import org.springframework.security.core.context.ReactiveSecurityContextHolder;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ServerWebExchange;
import reactor.core.publisher.Mono;

@Component
public class BrandContextFilter implements GlobalFilter {

    @Override
    public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
        return ReactiveSecurityContextHolder.getContext()
                .map(sc -> (Jwt) sc.getAuthentication().getPrincipal())
                .flatMap(jwt -> {
                    String authorizedTheme = jwt.getClaimAsString("defaultThemeId");
                    var request = exchange.getRequest().mutate()
                            .header("X-Resolved-Theme", authorizedTheme)
                            .build();
                    return chain.filter(exchange.mutate().request(request).build());
                });
    }
}
